using namespace seal;using namespace crisp;
void check(const std::vector<C>&a,const std::vector<C>&b){if(a.size()!=b.size())throw std::runtime_error("size");double err=0;for(size_t i=0;i<a.size();++i)err=std::max(err,std::abs(a[i]-b[i]));std::cout<<"max_error="<<err<<'\n';if(err>0.005)throw std::runtime_error("numerical mismatch");}
int main(){omp_set_num_threads(4);try{for(size_t degree:{8192,16384}){Parameters p;p.degree=degree;SEALContext ctx(p.make(),true,sec_level_type::tc128);if(!ctx.parameters_set())throw std::runtime_error(ctx.parameter_error_message());KeyGenerator kg(ctx);PublicKey pk;kg.create_public_key(pk);GaloisKeys g;kg.create_galois_keys(g);Encryptor en(ctx,pk);Decryptor de(ctx,kg.secret_key());Evaluator ev(ctx);CKKSEncoder enc(ctx);
 for(auto dims:{std::pair<size_t,size_t>{100,256},{10,100},{10,1024},{7,13},{8,13}}){size_t m=dims.first,n=dims.second;std::vector<double>w(m*n);for(size_t i=0;i<w.size();++i)w[i]=m==8?0:int(i%7)-3;std::vector<C>x(n);for(size_t i=0;i<n;++i)x[i]=C(int(i%11)-5,int(i%13)-6);FCPlan plan(m,n,w,enc,p.scale);Plaintext pt;enc.encode(plan.pack(x),p.scale,pt);Ciphertext ct;en.encrypt(pt,ct);auto y=plan.eval(ct,ev,g,en);de.decrypt(y,pt);std::vector<C>z;enc.decode(pt,z);check(plan.unpack(z),plain_fc(m,n,w,x));}
 for(auto sh:{ConvShape{5,5,3,5,3,1},ConvShape{28,28,1,16,5,0},ConvShape{8,8,9,17,1,0}}){std::vector<double>w(sh.ci*sh.co*sh.k*sh.k);for(size_t i=0;i<w.size();++i)w[i]=(int(i%7)-3)*.125;std::vector<C>x(sh.ci*sh.h*sh.w);for(size_t i=0;i<x.size();++i)x[i]=C(int(i%11)-5,int(i%13)-6);ConvPlan plan(sh,w,enc,p.scale);auto packed=plan.pack(x);std::vector<Ciphertext>ct(packed.size());Plaintext pt;for(size_t i=0;i<ct.size();++i){enc.encode(packed[i],p.scale,pt);en.encrypt(pt,ct[i]);}auto y=plan.eval(ct,ev,enc,g,4,en);std::vector<std::vector<C>>z(y.size());for(size_t i=0;i<y.size();++i){de.decrypt(y[i],pt);enc.decode(pt,z[i]);}check(plan.unpack(z),plain_conv(sh,w,x));}
 }std::cout<<"PASS complex FC/conv vs independent plaintext, both degrees, non-power-of-two inputs, padding and channel tails\n";}catch(std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
